def decide(observation, memory):
    """Use a safety-gated finite-state controller with target confirmation,
    directional hysteresis, and bounded scan memory for stable progress.
    """
    memory = dict(memory or {})
    state = memory.get("state", "IDLE")
    scan_direction = memory.get("scan_direction", "SCAN_LEFT")
    scan_ticks = int(memory.get("scan_ticks", 0))
    previous_action = memory.get("previous_action", "")

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    distance = observation["target_distance_class"]
    target_confidence = float(observation["target_confidence"])
    identity_confidence = float(observation["target_identity_confidence"])
    track_age = int(observation["track_age"])
    lost_steps = int(observation["lost_steps"])
    safety_confidence = float(observation["safety_confidence"])
    closing_risk = float(observation["closing_risk"])

    def emit(action, confidence, next_state):
        memory["state"] = next_state
        memory["previous_action"] = action
        return action, confidence, memory

    if safety_confidence < 0.60 or closing_risk >= 0.75:
        return emit("STOP", 0.99, "STOPPED")

    confirmed = visible and target_confidence >= 0.55 and identity_confidence >= 0.60
    if not confirmed:
        if state in {"LOCKED", "APPROACH", "REACQUIRE"} or lost_steps > 0:
            if lost_steps <= 1:
                return emit("STOP", 0.92, "REACQUIRE")
            scan_ticks += 1
        else:
            scan_ticks = 1

        if scan_ticks >= 2:
            scan_direction = (
                "SCAN_RIGHT" if scan_direction == "SCAN_LEFT" else "SCAN_LEFT"
            )
            scan_ticks = 0
        memory["scan_direction"] = scan_direction
        memory["scan_ticks"] = scan_ticks
        return emit(scan_direction, 0.75, "SEARCH")

    memory["scan_ticks"] = 0
    memory["scan_direction"] = scan_direction

    if track_age < 2:
        return emit("SLOW_DOWN", 0.80, "VERIFY")

    if distance == "near":
        heading_error = abs(float(observation["heading_error"]))
        if heading_error <= 15.0 and identity_confidence >= 0.80:
            return emit("ARRIVED", 0.96, "ARRIVED")
        turn = "VEER_LEFT" if bearing < 0 else "VEER_RIGHT"
        return emit(turn, 0.88, "APPROACH")

    desired = None
    if bearing < -12.0 and observation["corridor_left"]:
        desired = "VEER_LEFT"
    elif bearing > 12.0 and observation["corridor_right"]:
        desired = "VEER_RIGHT"
    elif observation["corridor_center"]:
        desired = "FORWARD"
    elif observation["corridor_left"]:
        desired = "VEER_LEFT"
    elif observation["corridor_right"]:
        desired = "VEER_RIGHT"

    if desired is None:
        return emit("STOP", 0.98, "STOPPED")

    # Preserve an ongoing correction in the small deadband to avoid oscillation.
    if desired == "FORWARD" and abs(bearing) < 6.0:
        if previous_action in {"VEER_LEFT", "VEER_RIGHT"}:
            desired = previous_action

    confidence = 0.90 if desired in {"FORWARD", "VEER_LEFT", "VEER_RIGHT"} else 0.82
    return emit(desired, confidence, "APPROACH")
